import{_ as i,o as e,c as a,a2 as o}from"./chunks/framework.CDA9RsCr.js";const v=JSON.parse('{"title":"开发日志","description":"","frontmatter":{},"headers":[],"relativePath":"development/changelog.md","filePath":"development/changelog.md","lastUpdated":1794581028000}'),t={name:"development/changelog.md"};function r(d,l,n,c,h,s){return e(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="开发日志" tabindex="-1">开发日志 <a class="header-anchor" href="#开发日志" aria-label="Permalink to &quot;开发日志&quot;">​</a></h1><h2 id="v1-6-0" tabindex="-1">v1.6.0 <a class="header-anchor" href="#v1-6-0" aria-label="Permalink to &quot;v1.6.0&quot;">​</a></h2><p>界面重构与实时观赛：</p><ul><li>选人页重做为「直播画面 + 频道列表 + 弹幕流 + 参数条」的单屏布局，窄窗口自动收起侧栏</li><li>新增实时弹幕面板：跟随当前频道、支持 B 站表情（含 <code>[oh]</code> 这类口令表情）、贴底跟随、上滚暂停、静置 3 秒自动恢复</li><li>新增内嵌直播播放器（HLS），带时钟看门狗：静默卡流时先软恢复，再重建播放器并换地址，退避上限 20 秒</li><li>主题改为「深浅色 + 背景预设」两层：春节、假日背景可选，主色调从背景图自动取色</li><li>界面改用 Tailwind + HeroUI，滚动条只在滚动时显现；出结果时直播画面保持比例，中选名单占剩余高度在卡片内滚动</li><li>图片链路优化：限并发预解码队列、B 站 CDN 缩略图、可见区懒加载，弹幕刷屏时主线程卡顿明显下降</li><li>前端按功能域拆分（session / lottery / rooms / profiles / settings / history），后端 service 拆分出 room / danmaku_feed / emote / history</li><li>新增浏览器开发桥接：<code>/api/*</code> 与 Wails IPC 共用同一份业务代码，独立二进制 <code>cmd/devbridge</code> 复用同一路由</li><li>登录页支持卡片倾斜动效与主题切换；二维码状态机覆盖过期与已扫描待确认</li><li>口令留空即收集全部弹幕；添加频道支持直接粘贴直播间链接</li></ul><h2 id="v1-5-0" tabindex="-1">v1.5.0 <a class="header-anchor" href="#v1-5-0" aria-label="Permalink to &quot;v1.5.0&quot;">​</a></h2><ul><li>抽奖页实时显示参与人数，等待弹幕时有明确提示</li><li>关键词留空即收集全部弹幕，抽奖页会标明当前模式，无人参与时不再开奖</li><li>直播间连接失败会明确提示，避免「假装在积累」</li><li>中奖页支持一键复制名单</li><li>历史记录改用真实关键词与中奖人数，并只保留最近 100 条</li><li>网络异常不再误清登录态，配置文件权限收紧为 0600</li></ul><h2 id="v1-4-0" tabindex="-1">v1.4.0 <a class="header-anchor" href="#v1-4-0" aria-label="Permalink to &quot;v1.4.0&quot;">​</a></h2><ul><li><code>getDanmuInfo</code> 接入 WBI 签名，修复接口返回 <code>-352</code> 导致弹幕连不上的问题</li><li>弹幕握手补全 <code>uid</code> 与 <code>buvid3</code>，避免昵称被打码、UID 归零后参与者被合并成同一人</li><li>弹幕主机改用 <code>wss_port</code>（2245），旧 <code>getConf</code> 兜底路径保留 token 与主机列表</li><li>修复前端 <code>tsconfig.json</code> 多余的 <code>types</code> 配置，依赖与绑定缺失时不再报类型错误</li></ul><h2 id="v1-3-0" tabindex="-1">v1.3.0 <a class="header-anchor" href="#v1-3-0" aria-label="Permalink to &quot;v1.3.0&quot;">​</a></h2><ul><li>抽奖历史可展开查看中奖名单，列表按时间新到旧、超长时卡片内滚动</li><li>加房间支持直接粘贴直播间链接，自动解析房间号</li></ul><h2 id="v1-2-0" tabindex="-1">v1.2.0 <a class="header-anchor" href="#v1-2-0" aria-label="Permalink to &quot;v1.2.0&quot;">​</a></h2><ul><li>Windows EXE / NSIS 安装包自动构建，随 GitHub Release 发布</li><li>修正 Windows 打包的 npm 代理与 NSIS / WebView2 路径问题</li></ul><h2 id="v1-1" tabindex="-1">v1.1 <a class="header-anchor" href="#v1-1" aria-label="Permalink to &quot;v1.1&quot;">​</a></h2><ul><li>抽奖历史自动记录，绑定到对应配置，切换配置即切换历史</li><li>中奖名单一键导出为 Markdown，按「关键词-人数-时间」命名</li><li>中奖名单超长时卡片内滚动，抽奖页不再被撑出滚动条</li></ul><h2 id="v1-0" tabindex="-1">v1.0 <a class="header-anchor" href="#v1-0" aria-label="Permalink to &quot;v1.0&quot;">​</a></h2><ul><li>文档站上线，中英双语，GitHub Pages 自动部署</li><li>架构与数据流改用 Mermaid 图表，文档全面重写</li><li>修复消息弹窗跳动、扫码登录取不到 Cookie</li></ul><h2 id="v0-9" tabindex="-1">v0.9 <a class="header-anchor" href="#v0-9" aria-label="Permalink to &quot;v0.9&quot;">​</a></h2><ul><li>新增海滩主题，凑齐日间 / 夜间 / 春节 / 海滩四套</li><li>Light / Dark 按 Cirrus 规范重做，纯 CSS、胶囊圆角、双层阴影</li><li>内置中英双语切换，默认中文</li></ul><h2 id="v0-8" tabindex="-1">v0.8 <a class="header-anchor" href="#v0-8" aria-label="Permalink to &quot;v0.8&quot;">​</a></h2><ul><li>升级 Wails v3，换用 Taskfile 构建</li><li>后端分层重写：app → service → domain + event，service 不再依赖 Wails</li><li>删掉没人用的动态抽奖死代码</li><li>接入 <code>live:user_join</code> 事件，参与人数实时跳动</li></ul><h2 id="v0-7" tabindex="-1">v0.7 <a class="header-anchor" href="#v0-7" aria-label="Permalink to &quot;v0.7&quot;">​</a></h2><ul><li>多套抽奖配置，各存各的关键词、房间、背景，一键切换</li><li>扫码登录上线，和 Cookie 登录二选一</li><li>弹幕连接断了自动重连</li></ul><h2 id="v0-6" tabindex="-1">v0.6 <a class="header-anchor" href="#v0-6" aria-label="Permalink to &quot;v0.6&quot;">​</a></h2><ul><li>初版：监听弹幕、关键词匹配、UID 去重、随机开奖</li></ul>',24)])])}const m=i(t,[["render",r]]);export{v as __pageData,m as default};
